import '../npc/npc_content.dart';
import 'runtime_game_state.dart';

class PeopleFactSnapshot {
  const PeopleFactSnapshot({
    required this.id,
    required this.category,
    required this.label,
    required this.description,
  });

  final String id;
  final String category;
  final String label;
  final String description;

  @override
  bool operator ==(Object other) =>
      other is PeopleFactSnapshot &&
      other.id == id &&
      other.category == category &&
      other.label == label &&
      other.description == description;

  @override
  int get hashCode => Object.hash(id, category, label, description);
}

class PersonSnapshot {
  const PersonSnapshot({
    required this.npcId,
    required this.displayName,
    required this.pronouns,
    required this.portraitPath,
    required this.affinity,
    required this.levelOneAffinity,
    required this.levelLabel,
    required this.facts,
  });

  final String npcId;
  final String displayName;
  final String pronouns;
  final String portraitPath;
  final int affinity;
  final int levelOneAffinity;
  final String? levelLabel;
  final List<PeopleFactSnapshot> facts;

  @override
  bool operator ==(Object other) =>
      other is PersonSnapshot &&
      other.npcId == npcId &&
      other.displayName == displayName &&
      other.pronouns == pronouns &&
      other.portraitPath == portraitPath &&
      other.affinity == affinity &&
      other.levelOneAffinity == levelOneAffinity &&
      other.levelLabel == levelLabel &&
      _listEquals(other.facts, facts);

  @override
  int get hashCode => Object.hash(
    npcId,
    displayName,
    pronouns,
    portraitPath,
    affinity,
    levelOneAffinity,
    levelLabel,
    Object.hashAll(facts),
  );
}

class PeopleSnapshot {
  const PeopleSnapshot(this.people);

  factory PeopleSnapshot.fromRuntimeState(
    RuntimeGameState state,
    NpcCatalog catalog,
  ) {
    final people = <PersonSnapshot>[];
    for (final package in catalog.npcs) {
      final relationship = state.relationships[package.id];
      if (relationship == null || relationship.seenDialogueIds.isEmpty) {
        continue;
      }
      final facts =
          [
            for (final fact in package.runtime.facts)
              if (relationship.learnedFactIds.contains(fact.id))
                PeopleFactSnapshot(
                  id: fact.id,
                  category: fact.category,
                  label: fact.label,
                  description: fact.description,
                ),
          ]..sort((left, right) {
            final category = left.category.compareTo(right.category);
            return category != 0 ? category : left.label.compareTo(right.label);
          });
      people.add(
        PersonSnapshot(
          npcId: package.id,
          displayName: package.runtime.displayName,
          pronouns: package.runtime.pronouns,
          portraitPath:
              package.visuals.portraitPaths['official-neutral'] ??
              package.visuals.portraitPaths.values.first,
          affinity: relationship.affinity,
          levelOneAffinity: package.runtime.relationship.levelOneAffinity,
          levelLabel: package.runtime.relationship.labelForLevel(
            relationship.level,
          ),
          facts: List.unmodifiable(facts),
        ),
      );
    }
    people.sort((left, right) => left.displayName.compareTo(right.displayName));
    return PeopleSnapshot(List.unmodifiable(people));
  }

  final List<PersonSnapshot> people;

  @override
  bool operator ==(Object other) =>
      other is PeopleSnapshot && _listEquals(other.people, people);

  @override
  int get hashCode => Object.hashAll(people);
}

bool _listEquals<T>(List<T> left, List<T> right) {
  if (left.length != right.length) {
    return false;
  }
  for (var index = 0; index < left.length; index++) {
    if (left[index] != right[index]) {
      return false;
    }
  }
  return true;
}
